"""Independent saved-original structural audit for business-alley capture.

This checks source binding and completeness. Actual visibility and statutory
judgment still require review of real Native output and legal source context.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path
import zipfile

from alley_activity import measure_original_activity
from alley_construction import ASSIGNMENT, VARIANTS
from native_acquisition import CAMERAS, FRAME_COUNT


def _json(path):
    if not path.is_file() or path.is_symlink():
        raise ValueError("original source missing: " + path.name)
    return json.loads(path.read_text())


def audit(path, case_id, *, require_native_attestation=False):
    """Return source-bound structural findings from one immutable attempt."""
    if not case_id.startswith(ASSIGNMENT + "__") or case_id.removeprefix(ASSIGNMENT + "__") not in VARIANTS:
        raise ValueError("wrong exact business-alley case")
    root = Path(path)
    inventory = _json(root / "inventory.json")
    expected = inventory.get("source_sha256")
    if not isinstance(expected, dict) or set(expected) != {
            "site.json", "plan.json", "actors.json", "activity-seal.json",
            "frame-map.json", "activity-measurement.json"}:
        raise ValueError("saved original source inventory incomplete")
    for name, digest in expected.items():
        target = root / name
        if target.is_symlink() or hashlib.sha256(target.read_bytes()).hexdigest() != digest:
            raise ValueError("saved original source hash differs: " + name)
    plan = _json(root / "plan.json")
    actors = _json(root / "actors.json")
    site = _json(root / "site.json")
    frame_map = _json(root / "frame-map.json")
    if (inventory.get("case_id") != case_id or plan.get("case_id") != case_id or
            site.get("case_id") != case_id or frame_map.get("case_id") != case_id):
        raise ValueError("saved original case identity differs")
    if (inventory.get("source_kind") != "original_native" or
            inventory.get("frame_count") != FRAME_COUNT or inventory.get("rate_hz") != 20):
        raise ValueError("saved original inventory incomplete")
    if require_native_attestation and inventory.get("diagnostic_fixture") is not False:
        raise ValueError("diagnostic fixture cannot attest physical Native capture")
    if not isinstance(frame_map.get("frames"), list) or len(frame_map["frames"]) != FRAME_COUNT:
        raise ValueError("saved original frame map incomplete")
    for index, row in enumerate(frame_map["frames"]):
        if row.get("frame") != index or abs(row.get("time_s", -1) - index / 20) > 1e-5:
            raise ValueError("saved original frame map discontinuity")
        if index and (row.get("native_frame") != frame_map["frames"][index - 1]["native_frame"] + 1 or
                      abs(row.get("native_time_s", -1) - frame_map["frames"][index - 1]["native_time_s"] - 0.05) > 0.001):
            raise ValueError("saved Native frame map discontinuity")
    for label, key in (("ego", "ego_vehicle_id"), ("passenger", "passenger_actor_id"),
                       ("goods", "goods_actor_id"), ("driver", "driver_actor_id")):
        if not actors.get(key):
            raise ValueError("saved original " + label + " actor absent")
    if inventory.get("map_sha256") != site.get("reviewed_sources", {}).get("map", {}).get("sha256"):
        raise ValueError("saved map source binding differs")
    if hashlib.sha256((root / "road.xodr").read_bytes()).hexdigest() != inventory["map_sha256"]:
        raise ValueError("saved Native map hash differs")
    if not isinstance(inventory.get("media"), dict) or set(inventory["media"]) != CAMERAS:
        raise ValueError("saved original four-camera inventory incomplete")
    for name in CAMERAS:
        media = inventory["media"][name]
        filename = name + ".zip"
        if media.get("path") != filename:
            raise ValueError("original camera path differs")
        target = root / filename
        if target.is_symlink() or hashlib.sha256(target.read_bytes()).hexdigest() != media.get("sha256"):
            raise ValueError("original camera source hash differs: " + name)
        with zipfile.ZipFile(target) as archive:
            names = archive.namelist()
            if len(names) != FRAME_COUNT or len(set(names)) != FRAME_COUNT:
                raise ValueError("original camera frames incomplete: " + name)
            for index, entry in enumerate(names):
                native_frame = frame_map["frames"][index]["native_frame"]
                if entry != f"{index:04d}-{native_frame}.png" or not archive.read(entry).startswith(b"\x89PNG\r\n\x1a\n"):
                    raise ValueError("original camera frame invalid: " + name)
    activity = root / "activity.jsonl"
    if hashlib.sha256(activity.read_bytes()).hexdigest() != inventory.get("activity_sha256"):
        raise ValueError("saved original activity source hash differs")
    measured = measure_original_activity(activity, root / "activity-seal.json", case_id)
    if measured != _json(root / "activity-measurement.json"):
        raise ValueError("saved original activity measurement differs")
    return {"case_id": case_id, "structural_status": "passed",
            "frame_count": FRAME_COUNT, "camera_count": len(CAMERAS),
            "diagnostic_fixture": inventory["diagnostic_fixture"],
            "physical_completion": False, "legal_conclusion": "unreviewed",
            "activity_sha256": inventory["activity_sha256"]}

"""Independent source-bound contrasts for the five exact business-alley pairs."""
from __future__ import annotations

import json
from pathlib import Path

from alley_construction import ASSIGNMENT
from audit_original_attempt import audit

PAIRS = {
    "passenger_active_vs_waiting": ("passenger_active_stop", "passenger_wait_stand"),
    "passenger_stop_vs_driver_exit": ("passenger_active_stop", "passenger_driver_exit_park"),
    "passenger_vs_goods": ("passenger_active_stop", "goods_active_load"),
    "goods_active_vs_interrupted": ("goods_active_load", "goods_wait_interrupted"),
    "ordinance_override": ("passenger_active_stop", "ordinance_passenger_authorized"),
}
FIXED_SOURCES = ("map", "alley", "business_frontage", "jurisdiction",
                 "vehicle_blueprint", "passenger_actor", "goods_actor")


def _load(root, expected):
    root = Path(root)
    case_id = ASSIGNMENT + "__" + expected
    finding = audit(root, case_id)
    site = json.loads((root / "site.json").read_text())
    plan = json.loads((root / "plan.json").read_text())
    measure = json.loads((root / "activity-measurement.json").read_text())
    return finding, site, plan, measure


def _first(spans):
    return spans[0][0] if spans else None


def compare(comparison_id, original_a, original_b):
    """Prove a controlled physical contrast, leaving legal review unresolved."""
    if comparison_id not in PAIRS:
        raise ValueError("unknown exact business-alley comparison")
    first, second = PAIRS[comparison_id]
    a, site_a, plan_a, measure_a = _load(original_a, first)
    b, site_b, plan_b, measure_b = _load(original_b, second)
    for key in FIXED_SOURCES:
        if site_a.get("reviewed_sources", {}).get(key) != site_b.get("reviewed_sources", {}).get(key):
            raise ValueError("fixed reviewed source differs: " + key)
    for key in ("alley_kind", "business_district_reviewed", "jurisdiction_reviewed",
                "centerline_start_m", "centerline_end_m", "loading_station_m",
                "loading_bay_reviewed", "passenger_zone_xy_m", "goods_zone_xy_m"):
        if site_a.get(key) != site_b.get(key):
            raise ValueError("fixed surveyed alley condition differs: " + key)
    for key in ("target_xy_m", "approach_direction", "capture"):
        if plan_a.get(key) != plan_b.get(key):
            raise ValueError("fixed constructed capture differs: " + key)
    ia, ib = measure_a["intervals_s"], measure_b["intervals_s"]
    if not ia["halt"] or not ib["halt"]:
        raise ValueError("original vehicle halt absent")
    if comparison_id != "ordinance_override":
        if (site_a.get("ordinance_status"), site_b.get("ordinance_status")) != (
                "reviewed_no_applicable_override", "reviewed_no_applicable_override"):
            raise ValueError("fixed ordinance condition differs")
    if comparison_id == "passenger_active_vs_waiting":
        if (_first(ia["passenger_contact"]) is None or
                _first(ib["passenger_contact"]) is None or
                _first(ia["passenger_contact"]) >= _first(ib["passenger_contact"])):
            raise ValueError("original passenger engagement contrast absent")
    elif comparison_id == "passenger_stop_vs_driver_exit":
        if ia["driver_outside"] or not ib["driver_outside"]:
            raise ValueError("original driver-exit contrast absent")
    elif comparison_id == "passenger_vs_goods":
        if (not ia["passenger_contact"] or ia["goods_contact"] or
                ib["passenger_contact"] or not ib["goods_contact"]):
            raise ValueError("original passenger versus goods contrast absent")
    elif comparison_id == "goods_active_vs_interrupted":
        if len(ia["goods_contact"]) != 1 or len(ib["goods_contact"]) < 2:
            raise ValueError("original continuous versus interrupted goods contrast absent")
        if not all(ib["goods_contact"][i][1] < ib["goods_contact"][i + 1][0]
                   for i in range(len(ib["goods_contact"]) - 1)):
            raise ValueError("original goods idle interval absent")
    else:
        if (site_a.get("ordinance_status") != "reviewed_no_applicable_override" or
                site_b.get("ordinance_status") != "reviewed_authorizes_passenger_loading" or
                "ordinance" not in site_b.get("reviewed_sources", {}) or
                not ia["passenger_contact"] or not ib["passenger_contact"] or
                measure_a["ordinance_applicable_frames"] != 0 or
                measure_b["ordinance_applicable_frames"] == 0):
            raise ValueError("reviewed ordinance and original activity contrast absent")
    return {"comparison_id": comparison_id, "case_ids": [a["case_id"], b["case_id"]],
            "structural_status": "passed", "deliberate_contrast": "observed",
            "physical_completion": False, "legal_conclusion": "unreviewed"}

